       'GreatWorkObjectType', gw.GreatWorkObjectType
FROM NW_CourtOfLoveGreatWorkAmounts gw
CROSS JOIN NW_CourtOfLoveDistrictYields dy;
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Value)
