    'MINOR_CIV_BABYLON_GREAT_WORK_WRITING_SCIENCE',
    'MINOR_CIV_BABYLON_GREAT_WORK_RELIC_SCIENCE',
    'MINOR_CIV_BABYLON_GREAT_WORK_ARTIFACT_SCIENCE'
);

